/**
 * Vietnam's outline for the landing map: Natural Earth 1:50m admin-0 countries (public domain, naturalearthdata.com), the VNM shape,
 * simplified to 411 points. Generated by a one-off script; the projection constants below place any coordinate on it.
 */
export const MAP_VIEW = { width: 950, height: 1239 }

const LON0 = 102.0
const LAT0 = 23.6
const COS = 0.961262
const K = 76.0

/** A latitude and longitude as a point on the map (equirectangular, scaled by cos 16°). */
export const mapPoint = (lat: number, lng: number) => ({ x: (lng - LON0) * COS * K, y: (LAT0 - lat) * K })

